  7	final class BipartiteGraph {
  8	    private static final int UNCOLORED = -1;
  9	    private static final int FIRST_COLOR = 0;
 10	    private static final int SECOND_COLOR = 1;
 11	
 12	    private BipartiteGraph() {
 13	        // Utility class.
 14	    }
 15	
 16	    static List<List<Integer>> buildAdjacencyList(int vertexCount, int[][] edges) {
 17	        validateInputs(vertexCount, edges);
 18	
 19	        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
 20	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 21	            adjacencyList.add(new ArrayList<>());
 22	        }
 23	
 24	        for (int[] edge : edges) {
 25	            int source = edge[0];
 26	            int destination = edge[1];
 27	            adjacencyList.get(source).add(destination);
 28	            adjacencyList.get(destination).add(source);
 29	        }
 30	
 31	        return adjacencyList;
 32	    }
 33	
 34	    static boolean isBipartite(int vertexCount, int[][] edges) {
 35	        List<List<Integer>> adjacencyList = buildAdjacencyList(vertexCount, edges);
 36	        int[] colors = new int[vertexCount];
 37	        Arrays.fill(colors, UNCOLORED);
 38	
 39	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 40	            if (colors[vertex] == UNCOLORED
 41	                    && !isComponentBipartite(vertex, adjacencyList, colors)) {
 42	                return false;
 43	            }
 44	        }
 45	
 46	        return true;
 47	    }
 48	
 49	    private static boolean isComponentBipartite(
 50	            int startVertex,
 51	            List<List<Integer>> adjacencyList,
 52	            int[] colors) {
 53	        Deque<Integer> queue = new ArrayDeque<>();
 54	        colors[startVertex] = FIRST_COLOR;
 55	        queue.offer(startVertex);
 56	
 57	        while (!queue.isEmpty()) {
 58	            int currentVertex = queue.poll();
 59	
 60	            for (int neighbor : adjacencyList.get(currentVertex)) {
 61	                if (colors[neighbor] == UNCOLORED) {
 62	                    colors[neighbor] = oppositeColor(colors[currentVertex]);
 63	                    queue.offer(neighbor);
 64	                    continue;
 65	                }
 66	
 67	                if (colors[neighbor] == colors[currentVertex]) {
 68	                    return false;
 69	                }
 70	            }
 71	        }
 72	
 73	        return true;
 74	    }
 75	
 76	    private static int oppositeColor(int color) {
 77	        return color == FIRST_COLOR ? SECOND_COLOR : FIRST_COLOR;
 78	    }
