 80	    private static void validateInputs(int vertexCount, int[][] edges) {
 81	        if (vertexCount < 0) {
 82	            throw new IllegalArgumentException("Vertex count cannot be negative.");
 83	        }
 84	
 85	        if (edges == null) {
 86	            throw new IllegalArgumentException("Edges cannot be null.");
 87	        }
 88	
 89	        for (int edgeIndex = 0; edgeIndex < edges.length; edgeIndex++) {
 90	            int[] edge = edges[edgeIndex];
 91	            if (edge == null || edge.length != 2) {
 92	                throw new IllegalArgumentException(
 93	                        "Each edge must contain exactly two vertices. Invalid edge at index "
 94	                                + edgeIndex
 95	                                + ".");
 96	            }
 97	
 98	            validateVertex(edge[0], vertexCount, edgeIndex);
 99	            validateVertex(edge[1], vertexCount, edgeIndex);
100	        }
101	    }
