103	    private static void validateVertex(int vertex, int vertexCount, int edgeIndex) {
104	        if (vertex < 0 || vertex >= vertexCount) {
105	            throw new IllegalArgumentException(
106	                    "Edge at index "
107	                            + edgeIndex
108	                            + " references invalid vertex "
109	                            + vertex
110	                            + " for graph size "
111	                            + vertexCount
112	                            + ".");
113	        }
114	    }
